"use client";

import Image from "next/image";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";

type GameCardProps = {
  title: string;
  image: string;
  subtitle?: string;
  priority?: boolean;
};

export default function GameCard({
  title,
  image,
  subtitle,
  priority = false,
}: GameCardProps) {
  // Motion values to track mouse position
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  // Add a springy physics feel to the rotation
  const mouseXSpring = useSpring(x, { stiffness: 150, damping: 20 });
  const mouseYSpring = useSpring(y, { stiffness: 150, damping: 20 });

  // Transform the mouse position into degrees of rotation (Max 12 degrees)
  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["12deg", "-12deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-12deg", "12deg"]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    
    // Calculate percentage from the center of the card (-0.5 to 0.5)
    const xPct = mouseX / width - 0.5;
    const yPct = mouseY / height - 0.5;
    x.set(xPct);
    y.set(yPct);
  };

  const handleMouseLeave = () => {
    x.set(0); // Snap back to center
    y.set(0); 
  };

  return (
    <motion.div
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{
        rotateY,
        rotateX,
        transformStyle: "preserve-3d",
      }}
      className="
        min-w-[180px]
        bg-zinc-900/60
        backdrop-blur-xl
        border
        border-zinc-800
        rounded-3xl
        hover:border-cyan-400/40
        hover:shadow-[0_0_25px_rgba(22,188,249,0.15)]
        transition-colors
        duration-300
        cursor-pointer
      "
    >
      {/* translateZ pops the image out toward the user in 3D space */}
      <div 
        className="relative w-full h-56 rounded-t-3xl overflow-hidden pointer-events-none"
        style={{ transform: "translateZ(40px)" }} 
      >
        <Image
          src={image}
          alt={title}
          fill
          priority={priority}
          className="object-cover"
          sizes="(max-width: 768px) 100vw, 200px"
        />
      </div>

      {/* translateZ pops the text out slightly less to create depth layering */}
      <div className="p-4 pointer-events-none" style={{ transform: "translateZ(25px)" }}>
        <h3 className="font-bold text-lg">{title}</h3>
        {subtitle && (
          <p className="text-zinc-500 text-sm mt-1">{subtitle}</p>
        )}
      </div>
    </motion.div>
  );
}